#![cfg(feature = "sdk")]

//! Spec v1.8 §4A.1c example (decision 149, #270): a read-only refresh
//! `sign-method` (`user.sign-token`) plus a separate write method
//! (`user.record-session`) behind `api/auth/v1/session`.
//! Fixture: tests/fixtures/refresh-session (structured sources; the locks are
//! generated by `regenerate_project`, exactly as `vibe build` does).
use std::fs;
use std::path::{Path, PathBuf};

use vibe::compile::{regenerate_project, CompileOptions};
use vibe::manifest::manifest_from_project;
use vibe::sign;
use vibe::validate::{validate_project, ValidateOptions};

fn copy_dir(src: &Path, dst: &Path) {
    fs::create_dir_all(dst).unwrap();
    for entry in fs::read_dir(src).unwrap() {
        let entry = entry.unwrap();
        let to = dst.join(entry.file_name());
        if entry.path().is_dir() {
            copy_dir(&entry.path(), &to);
        } else {
            fs::copy(entry.path(), to).unwrap();
        }
    }
}

fn copy_fixture() -> PathBuf {
    let root = std::env::temp_dir().join(format!("vibe-refresh-session-{}", uuid::Uuid::new_v4()));
    copy_dir(
        &PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/refresh-session"),
        &root,
    );
    root
}

async fn compile(root: &Path, check: bool) -> Result<(), String> {
    regenerate_project(&CompileOptions {
        root,
        llm: None,
        llm_config: None,
        check,
    })
    .await
    .map(|_| ())
    .map_err(|err| err.to_string())
}

fn validate(root: &Path) -> Result<(), String> {
    validate_project(&ValidateOptions {
        dev: false,
        root,
        deploy: false,
    })
    .map(|_| ())
    .map_err(|err| err.to_string())
}

#[tokio::test]
async fn refresh_session_example_passes_validate_and_build() {
    let root = copy_fixture();
    compile(&root, false)
        .await
        .unwrap_or_else(|err| panic!("{err}"));
    compile(&root, true)
        .await
        .unwrap_or_else(|err| panic!("{err}"));
    validate(&root).unwrap_or_else(|err| panic!("{err}"));

    let key = sign::load_or_create(&root).unwrap();
    // Local flow: vibe build (no approval).
    validate_project(&ValidateOptions {
        root: &root,
        deploy: true,
        dev: true,
    })
    .unwrap_or_else(|err| panic!("{err}"));
    let manifest = manifest_from_project(&root, &key).unwrap_or_else(|err| panic!("{err}"));

    let sign_token = manifest
        .methods
        .iter()
        .find(|m| m.target == "user.sign-token")
        .expect("user.sign-token in manifest");
    assert!(!sign_token.writes, "sign-method must be read-only");
    assert!(sign_token.steps.iter().all(|s| !s.writes));
    let record = manifest
        .methods
        .iter()
        .find(|m| m.target == "user.record-session")
        .expect("user.record-session in manifest");
    assert!(record.writes);
    assert!(record
        .steps
        .iter()
        .any(|s| s.params.iter().any(|p| p == "ctx.user.sub")));
    assert!(manifest
        .routes
        .iter()
        .any(|r| r.path == "/auth/v1/{slug}/refresh" && r.public));
    assert!(manifest
        .routes
        .iter()
        .any(|r| r.path == "/auth/v1/session" && !r.public));
    assert!(manifest
        .migrations
        .iter()
        .any(|m| m.statements.iter().any(|s| s.contains("last_device"))));
    let _ = fs::remove_dir_all(&root);
}

/// Decision 149: a sign-method that writes must fail validate (and build) with
/// REFRESH_SIGN_METHOD_WRITES.
#[tokio::test]
#[ignore = "enabled by the D149 code PR (#270): validate has no REFRESH_SIGN_METHOD_WRITES check yet"]
async fn refresh_session_example_writing_sign_method_is_rejected() {
    let root = copy_fixture();
    let path = root.join("models/user/methods/sign-token.md");
    let src = fs::read_to_string(&path).unwrap();
    let src = src.replace(
        "- writes: false\n- capabilities",
        "- writes: true\n- capabilities",
    );
    let src = src.replace(
        "### s3\n",
        "### s2b\n\n- op: query\n- table: users\n- sql: update users set last_device = $1 where id::text = $2\n- params: ['refresh', u.id]\n- writes: true\n- scope: pk\n- out: w\n\n### s3\n",
    );
    fs::write(&path, src).unwrap();
    let text = match compile(&root, false).await {
        Err(err) => err,
        Ok(()) => validate(&root).err().unwrap_or_default(),
    };
    assert!(text.contains("REFRESH_SIGN_METHOD_WRITES"), "{text}");
    assert!(text.contains("user.sign-token"), "{text}");
    let _ = fs::remove_dir_all(&root);
}
